function roomCodeFrom(input){try{const u=new URL(input);input=u.searchParams.get('room')||'';}catch{}const code=String(input||'').trim().toLowerCase();return /^[a-z0-9]{12,24}$/.test(code)?code:null;}
function makeCode(){return [...crypto.getRandomValues(new Uint8Array(10))].map(x=>x.toString(16).padStart(2,'0')).join('');}
