function layoutOverlay(){const box=$('stage').getBoundingClientRect();const p=S.members.get(S.selected)||(S.selected===S.self.id?myPerson():null);const o=p?.overlay||S.self.overlay;const el=$('cameraOverlay');const w=Math.min(o.size||230,box.width*.44);el.style.width=w+'px';const height=o.shape==='circle'?w:w*.625;el.style.left=clamp(o.x??.8)*Math.max(0,box.width-w-4)+'px';el.style.top=clamp(o.y??.76)*Math.max(0,box.height-height-4)+'px';}
function contentRect(){const stage=$('stage').getBoundingClientRect(),v=$('screenVideo');const w=v.videoWidth||1600,h=v.videoHeight||900,scale=Math.min(stage.width/w,stage.height/h);return {left:(stage.width-w*scale)/2,top:(stage.height-h*scale)/2,width:w*scale,height:h*scale};}
