async function shareScreen(test=false){
 if(!active()){openJoin('host');return;}if(S.shareStream){stopShare();return;}
 try{
 if(test){const generated=makeTestStream();S.testStop=generated.stop;await beginShare(generated.stream,true);return;}
 if(!navigator.mediaDevices?.getDisplayMedia){toast('Este navegador não permite capturar a tela. No computador, use Chrome, Edge ou Firefox. Você ainda pode assistir às transmissões.',true);return;}
 const p=PROFILES[S.quality];const stream=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:p.width,max:p.width},height:{ideal:p.height,max:p.height},frameRate:{ideal:p.fps,max:p.fps}},audio:$('shareSound').checked,systemAudio:$('shareSound').checked?'include':'exclude',selfBrowserSurface:'exclude',surfaceSwitching:'include'});await beginShare(stream,false);
 }catch(e){if(e.name==='NotAllowedError'||e.name==='AbortError')toast('Compartilhamento cancelado. A call continua.');else toast('Não consegui iniciar a captura de tela. Tente escolher outra aba ou janela.',true);}
}
async function beginShare(stream,test){S.shareStream=stream;S.self.screen=true;const track=stream.getVideoTracks()[0];if(track){track.contentHint=S.quality==='smooth'?'motion':'detail';track.onended=()=>stopShare();}S.screenStreams.set(S.self.id,stream);S.selected=S.self.id;if(S.joined)for(const id of S.members.keys())if(id!==S.self.id)callShare(id);if(S.demo)S.members.set(S.self.id,myPerson());broadcastSelf();renderStage();toast(test?'Quadro de teste ao vivo. Ele não captura sua tela.':'Tela compartilhada. Ative a câmera e arraste a janelinha.');}
function stopShare(notify=true){if(!S.shareStream)return;if(S.joined&&!S.leaving)broadcast({type:'share-stopped'});const stream=S.shareStream;S.shareStream=null;for(const t of stream.getTracks()){t.onended=null;t.stop();}S.testStop?.();S.testStop=null;S.self.screen=false;S.screenStreams.delete(S.self.id);for(const c of S.outScreenCalls.values())c.close();S.outScreenCalls.clear();if(!S.leaving){broadcastSelf();renderStage();if(notify)toast('O compartilhamento foi encerrado.');}}
function makeTestStream(){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=900;const ctx=canvas.getContext('2d');const start=performance.now();let tick=0;const draw=()=>{const t=(performance.now()-start)/1000;ctx.fillStyle='#151220';ctx.fillRect(0,0,1600,900);const gr=ctx.createRadialGradient(1000,250,0,1000,250,1000);gr.addColorStop(0,'#413064');gr.addColorStop(1,'#151220');ctx.fillStyle=gr;ctx.fillRect(0,0,1600,900);ctx.strokeStyle='#ffffff08';ctx.lineWidth=1;for(let x=0;x<1600;x+=64){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,900);ctx.stroke();}for(let y=0;y<900;y+=64){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(1600,y);ctx.stroke();}ctx.fillStyle='#bfa1ff';ctx.font='600 24px system-ui';ctx.fillText('BR2002 / QUADRO DE TESTE',100,130);ctx.fillStyle='#f4edff';ctx.font='600 100px system-ui';ctx.fillText('A tropa tá on.',95,300);ctx.fillStyle='#a798c0';ctx.font='30px system-ui';ctx.fillText('Movimento real, gerado neste navegador.',100,365);const x=200+((t*160)%1200);ctx.fillStyle='#9b77f6';ctx.beginPath();ctx.arc(x,590,54,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#bd9dff33';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(100,590);ctx.lineTo(1500,590);ctx.stroke();ctx.fillStyle='#81d9b4';ctx.font='24px monospace';ctx.fillText('TEMPO '+t.toFixed(1)+'s    QUADRO '+(++tick),100,785);ctx.fillStyle='#79698f';ctx.font='21px system-ui';ctx.fillText('Nenhuma aba ou tela sua está sendo capturada.',100,830);};draw();const interval=setInterval(draw,1000/30);return {stream:canvas.captureStream(30),stop:()=>clearInterval(interval)};}
async function demo(){if(S.joined){toast('Você já está em uma call real. Abra os ajustes para enviar um quadro de teste.');return;}if(S.demo)return;await createMedia();S.demo=true;S.self.name=S.self.name||'Você';S.members.set(S.self.id,myPerson());const test=makeTestStream();S.demoStop=test.stop;await beginShare(test.stream,true);renderControls();renderPeople();$('demoRibbon').hidden=false;toast('Prévia local. Experimente arrastar a câmera, desenhar e entrar no modo foco.');}
async function invite(){if(!S.joined){openJoin('host');return;}const url=inviteURL();try{await navigator.clipboard.writeText(url);toast('Convite copiado! Mande o link para a tropa.');}catch{let dialog=$('inviteDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='inviteDialog';dialog.innerHTML='<div class="modal-heading"><h2>Convide a tropa.</h2><button class="icon-btn" data-close="inviteDialog" aria-label="Fechar">'+icon('x')+'</button></div><p class="settings-note">Copie este link e envie para os seus amigos.</p><input readonly aria-label="Link da sala"><p class="settings-note">Até 6 pessoas. O criador mantém a aba aberta para novas entradas.</p>';document.body.append(dialog);}dialog.querySelector('input').value=url;dialog.showModal();dialog.querySelector('input').select();}}
function validPoll(p){if(!p||typeof p.id!=='string'||!Array.isArray(p.options)||p.options.length!==2)return null;const votes={};for(const [id,v] of Object.entries(p.votes||{}).slice(0,6))if([0,1].includes(v))votes[id]=v;return{id:p.id.slice(0,50),question:String(p.question||'Enquete').slice(0,90),options:p.options.map(x=>String(x).slice(0,45)),author:String(p.author||''),votes,closed:!!p.closed};}
function renderPoll(){const card=$('pollCard');card.replaceChildren();if(!S.poll||!S.joined){card.hidden=true;return;}card.hidden=false;const p=S.poll,title=document.createElement('h4');title.textContent=p.question;card.append(title);const vals=Object.values(p.votes),total=vals.length;for(let i=0;i<2;i++){const count=vals.filter(v=>v===i).length,percent=total?Math.round(count/total*100):0;const b=document.createElement('button');b.className='poll-choice'+(p.votes[S.self.id]===i?' voted':'');b.style.setProperty('--vote-width',percent+'%');const fill=document.createElement('i'),name=document.createElement('b'),n=document.createElement('span');name.style.fontWeight='500';name.textContent=p.options[i];n.textContent=percent+'%';b.append(fill,name,n);b.disabled=p.closed;b.onclick=()=>{p.votes[S.self.id]=i;broadcast({type:'poll-vote',id:p.id,option:i});renderPoll();};card.append(b);}const small=document.createElement('small');small.textContent=total+' '+(total===1?'voto':'votos')+(p.closed?' · encerrada':' · você pode mudar seu voto');card.append(small);if(!p.closed&&(p.author===S.self.id||S.host)){const b=document.createElement('button');b.textContent='Encerrar enquete';b.onclick=()=>{p.closed=true;broadcast({type:'poll-close',id:p.id});renderPoll();};card.append(b);}}
function receiveMessage(msg,render=true){if(!msg||!msg.id||S.seen.has(msg.id))return;S.seen.add(msg.id);S.history.push({id:String(msg.id).slice(0,50),type:msg.type==='notice'?'notice':'message',from:String(msg.from||''),name:cleanName(msg.name),avatar:AVATARS.includes(msg.avatar)?msg.avatar:'👾',text:String(msg.text||'').slice(0,800),at:Number(msg.at)||Date.now()});if(S.history.length>100)S.history.shift();if(S.seen.size>500)S.seen=new Set(S.history.map(x=>x.id));if(render)renderMessages();}
function addNotice(text,id=uuid()){receiveMessage({type:'notice',id,text,at:Date.now()});}
function renderMessages(){const root=$('messages'),nearBottom=root.scrollHeight-root.scrollTop-root.clientHeight<100;root.replaceChildren();if(!S.history.length){const n=document.createElement('div');n.className='system-note';n.innerHTML='O chat fica só nesta call.<br>Sem histórico depois que a sala termina.';root.append(n);}for(const msg of S.history){if(msg.type==='notice'){const el=document.createElement('div');el.className='chat-notice';el.textContent=msg.text;root.append(el);continue;}const el=document.createElement('div');el.className='chat-message';const av=document.createElement('div');av.className='chat-message-avatar';av.textContent=msg.avatar;const body=document.createElement('div');body.className='chat-message-body';const meta=document.createElement('div');meta.className='chat-message-meta';const name=document.createElement('strong');name.textContent=msg.name;const time=document.createElement('time');time.textContent=new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(msg.at);const text=document.createElement('p');text.textContent=msg.text;meta.append(name,time);body.append(meta,text);el.append(av,body);root.append(el);}if(nearBottom)root.scrollTop=root.scrollHeight;$('chatCount').textContent=S.history.filter(x=>x.type==='message').length;}
function flyReaction(emoji,name){if(S.reduceMotion){toast(emoji+' '+name);return;}for(let i=0;i<7;i++){const el=document.createElement('span');el.className='flying-reaction';el.textContent=emoji;el.style.setProperty('--x',(12+Math.random()*76)+'%');el.style.setProperty('--size',(25+Math.random()*20)+'px');el.style.animationDelay=(i*.07)+'s';$('reactionLayer').append(el);setTimeout(()=>el.remove(),3400);}announce(name+' reagiu '+emoji);}
function react(emoji){if(!active()){toast('Entre na call ou explore a prévia para reagir.');return;}if(Date.now()-S.lastReaction<900)return;S.lastReaction=Date.now();flyReaction(emoji,S.self.name||'Você');if(S.joined)broadcast({type:'reaction',emoji});$('reactionsPopover').hidden=true;}
function playSound(kind){if(S.deaf)return;try{const AC=window.AudioContext||window.webkitAudioContext;sfxContext??=new AC();sfxContext.resume();const presets={win:[[523,.11],[659,.11],[784,.14],[1047,.22]],twist:[[330,.13],[247,.17],[196,.25]],suspense:[[110,.16],[116,.16],[110,.16],[123,.25]],gg:[[698,.09],[880,.09],[1047,.2]]};let time=sfxContext.currentTime;for(const [freq,dur] of presets[kind]||[]){const osc=sfxContext.createOscillator(),gain=sfxContext.createGain();osc.type=kind==='twist'?'triangle':'sine';osc.frequency.value=freq;gain.gain.setValueAtTime(0,time);gain.gain.linearRampToValueAtTime(.09,time+.01);gain.gain.exponentialRampToValueAtTime(.001,time+dur);osc.connect(gain);gain.connect(sfxContext.destination);osc.start(time);osc.stop(time+dur+.01);time+=dur;}}catch{}}
function randomInt(max){const limit=Math.floor(4294967296/max)*max;let n;do{n=crypto.getRandomValues(new Uint32Array(1))[0];}while(n>=limit);return n%max;}
function validTimer(t){if(!t||!Number.isFinite(t.remaining))return null;return{running:!!t.running,endAt:Number.isFinite(t.endAt)?t.endAt:0,remaining:clamp(t.remaining,0,25*60*1000)};}
function updateTimer(){let left=S.timer?S.timer.running?Math.max(0,S.timer.endAt-Date.now()):S.timer.remaining:25*60*1000;if(S.timer?.running&&left===0){S.timer.running=false;S.timer.remaining=0;toast('🍅 Foco concluído. Hora de respirar!');if(S.hearSfx)playSound('win');}const seconds=Math.ceil(left/1000);$('timerLabel').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('timerBtn').textContent=S.timer?.running?'Pausar foco':S.timer&&left>0&&left<25*60*1000?'Continuar foco':'Começar foco';}
setInterval(updateTimer,500);
function validStroke(s){return s&&typeof s.id==='string'&&Array.isArray(s.points)&&s.points.length>1&&s.points.length<=300&&s.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&n>=0&&n<=1));}
function renderDrawings(){const svg=$('drawingLayer');svg.replaceChildren();for(const stroke of S.drawings.get(S.selected)||[]){const line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('points',stroke.points.map(p=>p[0]*1000+','+p[1]*1000).join(' '));svg.append(line);}}
function showLaser(id,x,y,name){let dot=[...$('laserLayer').children].find(el=>el.dataset.peer===id);if(!dot){dot=document.createElement('div');dot.className='laser-dot';dot.dataset.peer=id;const label=document.createElement('span');label.textContent=name;dot.append(label);$('laserLayer').append(dot);}dot.style.left=x*100+'%';dot.style.top=y*100+'%';clearTimeout(dot._timeout);dot._timeout=setTimeout(()=>dot.remove(),750);}
function pointerCoords(e){const r=$('drawingLayer').getBoundingClientRect();return[clamp((e.clientX-r.left)/r.width),clamp((e.clientY-r.top)/r.height)];}
let drawing=null,lastLaser=0,drag=null;
$('drawingLayer').addEventListener('pointerdown',e=>{if(!S.selected||!S.drawMode)return;e.preventDefault();$('drawingLayer').setPointerCapture(e.pointerId);const point=pointerCoords(e);if(S.drawMode==='draw'){drawing={id:uuid(),points:[point]};const strokes=S.drawings.get(S.selected)||[];strokes.push(drawing);S.drawings.set(S.selected,strokes.slice(-40));renderDrawings();}else sendLaser(point);});
$('drawingLayer').addEventListener('pointermove',e=>{if(!S.drawMode)return;const point=pointerCoords(e);if(S.drawMode==='laser'){if(Date.now()-lastLaser>45){lastLaser=Date.now();sendLaser(point);}return;}if(drawing&&e.buttons){if(drawing.points.length<300)drawing.points.push(point);renderDrawings();}});
function endDraw(){if(drawing){if(drawing.points.length>1&&S.joined)broadcast({type:'stroke',presenter:S.selected,stroke:drawing});drawing=null;}}
$('drawingLayer').addEventListener('pointerup',endDraw);$('drawingLayer').addEventListener('pointercancel',endDraw);
function sendLaser(point){showLaser(S.self.id,...point,S.self.name||'Você');if(S.joined)broadcast({type:'laser',presenter:S.selected,x:point[0],y:point[1]});}
function setDrawMode(mode){if(!S.selected){toast('Abra uma transmissão ou a prévia primeiro.');return;}S.drawMode=S.drawMode===mode?null:mode;$('stage').classList.toggle('drawing',S.drawMode==='draw');$('stage').classList.toggle('lasering',S.drawMode==='laser');$('drawBtn').setAttribute('aria-pressed',S.drawMode==='draw');$('laserBtn').setAttribute('aria-pressed',S.drawMode==='laser');layoutDrawing();}
$('cameraOverlay').addEventListener('pointerdown',e=>{if(S.selected!==S.self.id)return;e.preventDefault();const el=$('cameraOverlay'),stage=$('stage').getBoundingClientRect(),r=el.getBoundingClientRect();drag={pointer:e.pointerId,dx:e.clientX-r.left,dy:e.clientY-r.top};el.setPointerCapture(e.pointerId);});
$('cameraOverlay').addEventListener('pointermove',e=>{if(!drag)return;const stage=$('stage').getBoundingClientRect(),r=$('cameraOverlay').getBoundingClientRect();S.self.overlay.x=clamp((e.clientX-stage.left-drag.dx)/Math.max(1,stage.width-r.width));S.self.overlay.y=clamp((e.clientY-stage.top-drag.dy)/Math.max(1,stage.height-r.height));S.members.set(S.self.id,myPerson());layoutOverlay();if(S.joined&&Date.now()-overlayBroadcastAt>100){overlayBroadcastAt=Date.now();broadcast({type:'state',person:myPerson()});}});
function endDrag(){if(drag){drag=null;broadcastSelf();}}
$('cameraOverlay').addEventListener('pointerup',endDrag);$('cameraOverlay').addEventListener('pointercancel',endDrag);
async function refreshDevices(){if(!navigator.mediaDevices?.enumerateDevices)return;try{const devices=await navigator.mediaDevices.enumerateDevices();for(const [id,kind,word] of [['micSelect','audioinput','Microfone'],['camSelect','videoinput','Câmera']]){const select=$(id),old=select.value;select.replaceChildren(new Option('Padrão do sistema',''));devices.filter(d=>d.kind===kind).forEach((d,i)=>select.add(new Option(d.label||word+' '+(i+1),d.deviceId)));if([...select.options].some(o=>o.value===old))select.value=old;}}catch{toast('Não consegui listar os dispositivos. Confira as permissões do navegador.');}}
function openSettings(tab='stream'){$('settingsDialog').showModal();setSettingsTab(tab);$('qualitySelect').value=S.quality;$('accentSelect').value=S.accent;$('reduceMotion').checked=S.reduceMotion;$('mirrorCam').checked=S.self.overlay.mirror;}
function setSettingsTab(tab){document.querySelectorAll('[data-settings-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.settingsTab===tab));for(const id of ['stream','devices','look'])$('settings-'+id).hidden=id!==tab;if(tab==='devices')refreshDevices();}
function setAccent(value){S.accent=value;const colors={violet:['#9675ff','150,117,255'],mint:['#69d5bd','105,213,189'],coral:['#f39aaf','243,154,175']};const c=colors[value]||colors.violet;document.documentElement.style.setProperty('--accent',c[0]);document.documentElement.style.setProperty('--accent-rgb',c[1]);pref('accent',value);}
function focusMode(){const on=$('app').classList.toggle('focus-mode');$('focusBtn').setAttribute('aria-pressed',on);requestAnimationFrame(()=>{layoutOverlay();layoutDrawing();});}
function toggleFun(open){const state=typeof open==='boolean'?open:$('funDrawer').hidden;$('funDrawer').hidden=!state;$('drawerBackdrop').hidden=!state;if(state)$('closeFun').focus();}
function toggleDeafen(){S.deaf=!S.deaf;renderPeople();renderStage();renderControls();toast(S.deaf?'Você silenciou o que ouve. Seu microfone não mudou.':'Áudio da call liberado.');}
function help(){$('helpDialog').showModal();}
// Real sender/receiver statistics; no invented FPS or latency values.
setInterval(async()=>{
 if(!S.joined)return;let selectedCall=S.selected&&S.selected!==S.self.id?S.inScreenCalls.get(S.selected):[...S.outScreenCalls.values()][0];selectedCall??=[...S.cameraCalls.values()][0];if(!selectedCall?.peerConnection){$('networkStats').textContent='Aguardando a tropa entrar.';return;}
 try{const pc=selectedCall.peerConnection,reports=await pc.getStats();let rtt=null,video=null,pair=null;reports.forEach(r=>{if(r.type==='candidate-pair'&&r.state==='succeeded'&&r.nominated)pair=r;if((r.type==='outbound-rtp'||r.type==='inbound-rtp')&&r.kind==='video'&&!r.isRemote)video=r;});if(pair?.currentRoundTripTime!=null)rtt=Math.round(pair.currentRoundTripTime*1000);let mbps=null;const key=selectedCall.connectionId,prev=S.stats.get(key),bytes=video?.bytesSent??video?.bytesReceived;if(video&&Number.isFinite(bytes)){if(prev&&video.timestamp>prev.at)mbps=(bytes-prev.bytes)*8/(video.timestamp-prev.at)/1000;S.stats.set(key,{bytes,at:video.timestamp});}
 const bits=[];if(Number.isFinite(video?.framesPerSecond))bits.push(Math.round(video.framesPerSecond)+' fps');if(mbps!=null)bits.push(mbps.toFixed(1).replace('.',',')+' Mb/s');if(rtt!=null)bits.push(rtt+' ms');$('networkStats').textContent=bits.length?bits.join(' · '):'Conexão direta estabelecida.';
 // Reduce only this receiver's screen bitrate under sustained congestion.
 if(rtt>350&&S.outScreenCalls.has(selectedCall.peer)){const sender=pc.getSenders().find(s=>s.track?.kind==='video');if(sender){const p=sender.getParameters();if(p.encodings?.length){p.encodings[0].maxBitrate=Math.max(900000,Math.round((p.encodings[0].maxBitrate||PROFILES[S.quality].bitrate)*.8));await sender.setParameters(p).catch(()=>{});}}}
 }catch{}
},3500);
$('joinForm').addEventListener('submit',async e=>{e.preventDefault();if(S.connecting)return;S.self.name=cleanName($('nickname').value);pref('name',S.self.name);pref('avatar',S.self.avatar);if(S.intent==='profile'){$('joinDialog').close();broadcastSelf();return;}const code=S.intent==='join'?roomCodeFrom($('roomCode').value):null;if(S.intent==='join'&&!code){toast('Cole o link completo ou o código inteiro da sala.',true);return;}const btn=$('joinSubmit'),old=btn.innerHTML;btn.disabled=true;btn.textContent='Conectando…';try{await joinRoom(S.intent,code,$('joinMic').checked);}catch(err){toast(err.message||'Não foi possível entrar na sala.',true);}finally{btn.disabled=false;btn.innerHTML=old;}});
$('avatarChoices').addEventListener('click',e=>{const b=e.target.closest('[data-avatar]');if(!b)return;S.self.avatar=b.dataset.avatar;$('avatarChoices').querySelectorAll('button').forEach(x=>x.classList.toggle('chosen',x===b));});
for(const id of ['createBtn','emptyInvite'])$(id).onclick=()=>openJoin('host');$('joinBtn').onclick=()=>openJoin('join');for(const id of ['inviteBtn','inviteSide'])$(id).onclick=invite;for(const id of ['profileBtn','selfAvatar'])$(id).onclick=()=>openJoin('profile');for(const id of ['settingsNav','selfSettings'])$(id).onclick=()=>openSettings('devices');$('qualityBtn').onclick=()=>openSettings('stream');for(const id of ['funNav','funSide','chatFunBtn'])$(id).onclick=()=>toggleFun(true);$('closeFun').onclick=()=>toggleFun(false);$('drawerBackdrop').onclick=()=>toggleFun(false);for(const id of ['homeBtn','callNav','roomNav'])$(id).onclick=()=>{toggleFun(false);$('app').classList.remove('sidebar-open');};$('helpBtn').onclick=help;$('demoBtn').onclick=()=>demo().catch(()=>toast('Não foi possível iniciar a prévia neste navegador.',true));$('micBtn').onclick=toggleMic;$('camBtn').onclick=toggleCamera;$('deafenBtn').onclick=toggleDeafen;for(const id of ['shareBtn','stageShareBtn'])$(id).onclick=()=>shareScreen();$('leaveBtn').onclick=()=>leaveRoom();$('focusBtn').onclick=focusMode;
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('stage').requestFullscreen)await $('stage').requestFullscreen();else toast('Este navegador não oferece tela cheia. Use o modo Foco.');}catch{toast('Não consegui abrir a tela cheia. Experimente o modo Foco.');}};
$('chatToggle').onclick=()=>{if(matchMedia('(max-width:1100px)').matches){const open=$('app').classList.toggle('chat-mobile-open');$('chatToggle').setAttribute('aria-pressed',open);}else{const closed=$('app').classList.toggle('chat-closed');$('chatToggle').setAttribute('aria-pressed',!closed);}};
$('mobileMenu').onclick=()=>$('app').classList.toggle('sidebar-open');$('reactionBtn').onclick=()=>{if(!active()){toast('Entre na call ou explore a prévia para reagir.');return;}$('reactionsPopover').hidden=!$('reactionsPopover').hidden;};
$('overlayToggle').onclick=()=>{S.self.overlay.enabled=!S.self.overlay.enabled;broadcastSelf();};$('overlaySize').onchange=()=>{S.self.overlay.size=Number($('overlaySize').value);broadcastSelf();};$('shapeBtn').onclick=()=>{const shapes=['round','circle','square'];S.self.overlay.shape=shapes[(shapes.indexOf(S.self.overlay.shape)+1)%3];broadcastSelf();};$('laserBtn').onclick=()=>setDrawMode('laser');$('drawBtn').onclick=()=>setDrawMode('draw');$('clearDraw').onclick=()=>{S.drawings.set(S.selected,[]);if(S.joined)broadcast({type:'clear-drawing',presenter:S.selected});renderDrawings();};
$('chatForm').addEventListener('submit',e=>{e.preventDefault();if(!S.joined)return;const text=$('chatInput').value.trim();if(!text)return;const msg={type:'message',id:uuid(),from:S.self.id,name:S.self.name,avatar:S.self.avatar,text:text.slice(0,800),at:Date.now()};receiveMessage(msg);broadcast(msg);$('chatInput').value='';});$('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('chatForm').requestSubmit();}});
$('pollForm').addEventListener('submit',e=>{e.preventDefault();if(!requireRoom())return;S.poll={id:uuid(),question:$('pollQuestion').value.trim(),options:[$('pollA').value.trim(),$('pollB').value.trim()],author:S.self.id,votes:{},closed:false};if(!S.poll.question||S.poll.options.some(x=>!x))return;broadcast({type:'poll-create',poll:S.poll});renderPoll();toast('Enquete no ar. A tropa decide!');toggleFun(false);$('app').classList.add('chat-mobile-open');});
$('diceBtn').onclick=()=>{if(!requireRoom())return;const value=randomInt(20)+1,text='🎲 D20: '+value+(value===20?' · crítico!':'');const id=uuid();addNotice(S.self.name+': '+text,id);broadcast({type:'notice',kind:'dice',id,text});toast(text);};$('rouletteBtn').onclick=()=>{if(!requireRoom())return;const people=[...S.members.values()];if(people.length<2){toast('Convide alguém primeiro. O sorteio precisa de companhia!');return;}const chosen=people[randomInt(people.length)];const text='🎯 Quem vai? '+chosen.name+'!';const id=uuid();addNotice(S.self.name+': '+text,id);broadcast({type:'notice',kind:'roulette',id,text});toast(text);};
$('timerBtn').onclick=()=>{if(!requireRoom())return;if(S.timer?.running)S.timer={running:false,remaining:Math.max(0,S.timer.endAt-Date.now()),endAt:0};else{const remaining=S.timer?.remaining||25*60*1000;S.timer={running:true,remaining,endAt:Date.now()+remaining};}broadcast({type:'timer',timer:S.timer});updateTimer();};$('hearSfx').onchange=()=>{S.hearSfx=$('hearSfx').checked;if(S.hearSfx)playSound('gg');};
$('qualitySelect').onchange=async()=>{S.quality=$('qualitySelect').value;pref('quality',S.quality);const p=PROFILES[S.quality];try{await S.shareStream?.getVideoTracks()[0]?.applyConstraints({width:{ideal:p.width,max:p.width},height:{ideal:p.height,max:p.height},frameRate:{ideal:p.fps,max:p.fps}});}catch{toast('O navegador manteve as dimensões disponíveis para esta captura.');}for(const c of S.outScreenCalls.values())configureMedia(c,'screen');renderControls();renderStage();};
$('testShareBtn').onclick=async()=>{if(!active()){toast('Entre em uma sala ou abra a prévia primeiro.');return;}$('settingsDialog').close();if(S.shareStream)stopShare(false);await shareScreen(true);};$('refreshDevices').onclick=refreshDevices;$('applyDevices').onclick=async()=>{try{if(!active()){toast('Entre na sala antes de aplicar os dispositivos.');return;}if(S.self.mic)await setMicrophone(true,true);if(S.self.cam)await setCamera(true,true);toast('Dispositivos atualizados.');}catch(e){toast(mediaError(e,'mic'),true);}};
$('accentSelect').onchange=()=>setAccent($('accentSelect').value);$('reduceMotion').onchange=()=>{S.reduceMotion=$('reduceMotion').checked;pref('reduceMotion',S.reduceMotion);$('app').classList.toggle('reduce-motion',S.reduceMotion);};$('mirrorCam').onchange=()=>{S.self.overlay.mirror=$('mirrorCam').checked;pref('mirror',S.self.overlay.mirror);broadcastSelf();};
document.querySelectorAll('[data-settings-tab]').forEach(b=>b.onclick=()=>setSettingsTab(b.dataset.settingsTab));
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close)$(close.dataset.close)?.close();const reaction=e.target.closest('[data-reaction]');if(reaction)react(reaction.dataset.reaction);const sound=e.target.closest('[data-sound]');if(sound){if(!requireRoom())return;if(Date.now()-S.lastSound<1800){toast('Uma pausa entre os efeitos faz bem pra call 😅');return;}S.lastSound=Date.now();playSound(sound.dataset.sound);broadcast({type:'sound',sound:sound.dataset.sound});}if(!e.target.closest('#reactionsPopover')&&!e.target.closest('#reactionBtn'))$('reactionsPopover').hidden=true;});
